questionvariables.text:
/* Listes de paramètres */
list_V: [1/2000, 1/1000, 1/500, 1/250, 1/125, 1/60, 1/30, 1/15, 1/8, 1/4, 1/2, 1, 2];
list_D_affichage: [1, 1.4, 2, 2.8, 4, 5.6, 8, 11, 16, 22];
list_D_reelles: [1, sqrt(2), 2, 2*sqrt(2), 4, 4*sqrt(2), 8, 8*sqrt(2), 16, 16*sqrt(2)];
list_I: [100, 200, 400, 800, 1600, 3200, 6400, 12800];

/* Tirage aléatoire */
valid: false;
while not valid do (
  idx_D1: rand(length(list_D_affichage)) + 1,
  D1_affichage: list_D_affichage[idx_D1],
  D1_reel: list_D_reelles[idx_D1],

  V1: rand(list_V),
  I1: rand(list_I),

  /* Constante d'exposition */
  K: float(V1 * I1 / D1_reel^2),

  /* Vitesse fixe, ISO change */
  V2: V1,
  I2: rand(delete(I1, list_I)),

  /* Calcul cible */
  D2_theorique_reel: sqrt(V2 * I2 / K),

  /* Trouver le diaphragme le plus proche */
  diffs: map(lambda([x], abs(float(x) - float(D2_theorique_reel))), list_D_reelles),
  min_diff: lmin(diffs),
  idx_D2: first(sublist(makelist(i, i, 1, length(list_D_reelles)), 
                        lambda([i], abs(float(list_D_reelles[i]) - float(D2_theorique_reel)) = min_diff))),

  D2_affichage: list_D_affichage[idx_D2],

  /* Validation : on veut que le résultat soit dans la liste et différent du départ */
  if (idx_D2 # idx_D1) then valid: true
);

/* Formatage pour l'affichage et l'arbre de réponse */
D1: D1_affichage;
V1_texte: string(V1);

/* IMPORTANT : d_cible doit être un string pour matcher avec les boutons radio */
d_cible: string(D2_affichage);

/* Format correct pour ta1 (conformément à vos instructions) */
ta1: map(lambda([x], [string(x), is(string(x) = d_cible), sconcat("f/", x)]), list_D_affichage);

/* Variables pour le feedback général */
diaphragme_ferme: if D2_affichage > D1 then true else false;
iso_augmente: if I2 > I1 then true else false;
vitesse_ralentie: if V2 > V1 then true else false;
n1_exact: (D1_reel/D2_reel)^2;
n2_exact: (D2_reel/D1_reel)^2;
n1: I2/I1;
n2: I1/I2;

n3: I2/I1;
n4: I1/I2;

n7_exact: if V2 > V1 then V2/V1 else V1/V2;
n7: 2^round(log(n7_exact)/log(2));
